def icon_exists(key):
    return key in LINE_ICONS or key in BRAND_ICONS


def icon_svg(key, size=20, css_class=''):
    """Inline <svg> for an icon key (unknown keys fall back to the folder)"""
    if key in BRAND_ICONS:
        return format_html('<svg class="sp-icon {}" viewBox="0 0 24 24" width="{}" height="{}" aria-hidden="true">{}</svg>',
                           css_class, size, size, mark_safe(BRAND_ICONS[key]))
    body = LINE_ICONS.get(key, LINE_ICONS['folder'])
    return format_html('<svg class="sp-icon {}" viewBox="0 0 24 24" width="{}" height="{}" fill="none" stroke="currentColor" '
                       'stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{}</svg>',
                       css_class, size, size, mark_safe(body))


def icon_catalog():
    """For the pickers in the browser: {"line": {key: body}, "brand": {key: body}}"""
    return {'line': LINE_ICONS, 'brand': BRAND_ICONS}
